<script setup lang="ts">
import { withBase } from 'vitepress'
import { computed } from 'vue'

import linkTheme from '../../../../packages/vue/src/components/link/theme'
import { tv } from '../../../../packages/vue/src/utils/tv'

// Port of HeroUI docs' component-item.tsx. Thumbnails are HareUI's own, generated by
// `bun scripts/gen-thumbnails.ts` into public/related-components/{light,dark}-<slug>.png.
const props = defineProps<{
  /** Page slug under /docs/components, e.g. `checkbox-group`. */
  slug: string
  title: string
}>()

// HeroUI's `link no-underline` classes: `.link` is the Link component's base style. Titles keep the foreground colour
// as on heroui.com; design themes that colour `--link` (e.g. Kumo) target inline prose links, not this grid.
const linkClass = tv(linkTheme)().base({ class: 'no-underline text-foreground' })

const href = computed(() => withBase(`/docs/components/${props.slug}`))
const lightSrc = computed(() => withBase(`/related-components/light-${props.slug}.png`))
const darkSrc = computed(() => withBase(`/related-components/dark-${props.slug}.png`))
</script>

<template>
  <div class="flex flex-col gap-[9px]">
    <!-- Title first on mobile, image first on desktop -->
    <div class="order-1 sm:order-2">
      <a :class="linkClass" :href="href">
        <div class="flex items-center gap-2">{{ title }}</div>
      </a>
    </div>
    <div
      class="relative order-2 h-[198px] overflow-hidden rounded-xl border border-separator sm:order-1"
    >
      <a class="h-full w-full" :href="href">
        <img
          :alt="title"
          class="absolute inset-0 block h-full w-full object-cover dark:hidden"
          decoding="async"
          height="594"
          loading="lazy"
          :src="lightSrc"
          width="874"
        />
        <img
          :alt="title"
          class="absolute inset-0 hidden h-full w-full object-cover dark:block"
          decoding="async"
          height="594"
          loading="lazy"
          :src="darkSrc"
          width="874"
        />
      </a>
    </div>
  </div>
</template>
